SELECT COUNT(*) FROM users u WHERE u.workspace_id=@workspace AND u.user_id=@user AND u.status='active' AND (u.allow_seller=1 OR COALESCE(u.managed_role,u.identity_role) IN ('owner','manager','demo')) AND (COALESCE(u.managed_role,u.identity_role) IN ('owner','manager','demo') OR EXISTS(SELECT 1 FROM user_memberships m WHERE m.workspace_id=u.workspace_id AND m.user_id=u.user_id AND m.property_id=@property));
